import { NextRequest, NextResponse } from 'next/server';

const UPSTREAM = process.env.LAMBDA_API_URL!;
const API_KEY  = process.env.LAMBDA_API_KEY!;

async function forward(req: NextRequest, params: Promise<{ path: string[] }>) {
  const { path } = await params;
  const url = `${UPSTREAM}/${path.join('/')}${req.nextUrl.search}`;

  const init: RequestInit = {
    method: req.method,
    headers: { 'Content-Type': 'application/json', 'x-api-key': API_KEY },
  };

  if (req.method !== 'GET' && req.method !== 'HEAD') {
    init.body = await req.text();
  }

  const upstream = await fetch(url, init);
  const text = await upstream.text();

  let body: unknown;
  try { body = JSON.parse(text); } catch { body = text; }

  console.log(`[Proxy] ${req.method} ${url} → ${upstream.status}`, body);
  return NextResponse.json(body, { status: upstream.status });
}

export const GET     = (req: NextRequest, ctx: { params: Promise<{ path: string[] }> }) => forward(req, ctx.params);
export const POST    = (req: NextRequest, ctx: { params: Promise<{ path: string[] }> }) => forward(req, ctx.params);
export const PUT     = (req: NextRequest, ctx: { params: Promise<{ path: string[] }> }) => forward(req, ctx.params);
export const DELETE  = (req: NextRequest, ctx: { params: Promise<{ path: string[] }> }) => forward(req, ctx.params);
export const PATCH   = (req: NextRequest, ctx: { params: Promise<{ path: string[] }> }) => forward(req, ctx.params);
